impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::ParseError(feature) => f.write_fmt(format_args!(
                "Experimental feature \"{feature}\" cannot be parsed."
            )),
