                let n_pos = chars.iter().position(|&c| c == 'n');
                let p_pos = chars.iter().position(|&c| c == 'p');
                // -n is in the combined flag and either:
                // - -p is not present, OR
                // - -n comes after -p (so -n takes effect)
                if let Some(n) = n_pos {
                    if p_pos.is_none() || n > p_pos.unwrap() {
                        return true;
                    }
                }
            }
            false
