fn serialize_field_sort_order<S: Serializer>(
    value: &Option<FieldSortOrder>,
    serializer: S,
) -> Result<S::Ok, S::Error> {
    if let Some(value) = value {
        match value {
            FieldSortOrder::Asc => serializer.serialize_str("asc"),
            FieldSortOrder::Desc => serializer.serialize_str("desc"),
